import{_ as d,C as r,o as e,c as i,a2 as o,E as l}from"./chunks/framework.CnJ-JtFX.js";const g=JSON.parse('{"title":"第 14 章 · 产品横向对比：五强横评，没有银弹","description":"","frontmatter":{},"headers":[],"relativePath":"guide/14-product-comparison.md","filePath":"guide/14-product-comparison.md","lastUpdated":1792683644000}'),s={name:"guide/14-product-comparison.md"};function n(h,t,m,u,c,p){const a=r("ComicFrame");return e(),i("div",null,[t[0]||(t[0]=o('<h1 id="第-14-章-·-产品横向对比-五强横评-没有银弹" tabindex="-1">第 14 章 · 产品横向对比：五强横评，没有银弹 <a class="header-anchor" href="#第-14-章-·-产品横向对比-五强横评-没有银弹" aria-label="Permalink to &quot;第 14 章 · 产品横向对比：五强横评，没有银弹&quot;">​</a></h1><blockquote class="meta"><p><strong>前置章节</strong>：<a href="./../guide/13-grapesjs-advanced">第 13 章 · GrapesJS 进阶</a><br><strong>所需环境</strong>：无（纯文档章节）；本章不建 lab，对照结论基于前 13 章的实测。<br><strong>难度</strong>：★<br><strong>本章交付物</strong>：5+2 产品对照矩阵、三问选型决策树、场景选型映射表、组合使用策略。</p></blockquote><p>走完五个主线产品（amis、Formily、lowcode-engine、tmagic-editor、GrapesJS），你应该能感受到一个事实：<strong>没有银弹</strong>。每个产品都在&quot;约束强度&quot;和&quot;灵活度&quot;的光谱上占据一个位置——amis 最约束（Schema 驱动一切），GrapesJS 最自由（直接操作 DOM），Formily/lowcode-engine/tmagic-editor 在中间各有侧重。</p><p>本章的目标是帮你建立选型直觉：面对一个具体需求，能用三问决策树快速定位到合适的产品，知道每个产品的&quot;甜蜜区&quot;和&quot;雷区&quot;，理解什么场景下该组合使用多个产品。本章不涉及新的代码和 lab，所有结论都基于前 13 章的实测。</p><h2 id="本章你将获得" tabindex="-1">本章你将获得 <a class="header-anchor" href="#本章你将获得" aria-label="Permalink to &quot;本章你将获得&quot;">​</a></h2><p>读完本章，你应该能完成四件事：</p><ol><li>说出五个主线产品在&quot;画布自由度 / DSL 形式 / 自定义组件协议 / 运行时分离 / 导出产物&quot;五个维度的差异；</li><li>用三问决策树（表单还是页面？自由还是约束？单端还是跨端？）快速选型；</li><li>看懂五强能力对照表，知道每个产品的&quot;甜蜜区&quot;和&quot;雷区&quot;；</li><li>理解组合使用策略——比如 amis 做页面 + Formily 做复杂表单、lowcode-engine 做设计器 + tmagic 做 H5 运行时。</li></ol><h2 id="先看漫画" tabindex="-1">先看漫画 <a class="header-anchor" href="#先看漫画" aria-label="Permalink to &quot;先看漫画&quot;">​</a></h2>',8)),l(a,{ep:"EP.14",slug:"product-comparison",title:"五强横评，没有银弹"}),t[1]||(t[1]=o('<p>这一话画的是选型焦虑——标签君面对五个产品不知道选哪个，像素酱用三问决策树（表单/页面？自由/约束？单端/跨端？）帮他定位，码叔结案&quot;没有银弹，按场景选型&quot;。逐格讲解、坑点清单和三道自测题在 <a href="./../comics/EP.14-product-comparison">EP.14 漫画讲解</a>。</p><h2 id="从一个真实问题说起" tabindex="-1">从一个真实问题说起 <a class="header-anchor" href="#从一个真实问题说起" aria-label="Permalink to &quot;从一个真实问题说起&quot;">​</a></h2><p>你接到一个需求：做一个&quot;客户运营后台&quot;，包含概览卡片、客户列表 CRUD、复杂表单（含联动/异步校验）、状态筛选、导出。团队问你：用哪个低代码产品？</p><p>如果你说&quot;用 amis&quot;，有人会问&quot;复杂表单的联动 Formily 不是更强吗？&quot;；如果你说&quot;用 lowcode-engine&quot;，有人会问&quot;运营同学能拖得动吗？学习成本多高？&quot;；如果你说&quot;用 GrapesJS&quot;，有人会问&quot;中后台表单能用自由画布做吗？&quot;。</p><p>选型焦虑的本质是：<strong>每个产品都有它擅长的场景，但没有产品能覆盖所有场景</strong>。本章给你一套决策框架，让你面对需求时不是&quot;拍脑袋选&quot;，而是&quot;按维度匹配&quot;。</p><h2 id="原理拆解" tabindex="-1">原理拆解 <a class="header-anchor" href="#原理拆解" aria-label="Permalink to &quot;原理拆解&quot;">​</a></h2><h3 id="五强能力对照矩阵" tabindex="-1">五强能力对照矩阵 <a class="header-anchor" href="#五强能力对照矩阵" aria-label="Permalink to &quot;五强能力对照矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>amis</th><th>Formily</th><th>lowcode-engine</th><th>tmagic-editor</th><th>GrapesJS</th></tr></thead><tbody><tr><td>核心定位</td><td>Schema 驱动中后台</td><td>表单领域模型</td><td>可视化编排内核</td><td>页面搭建器</td><td>自由画布编辑器</td></tr><tr><td>画布自由度</td><td>低（Schema 约束）</td><td>中（表单字段模型）</td><td>中高（物料协议）</td><td>中（绝对布局 DSL）</td><td>高（直接 DOM）</td></tr><tr><td>DSL 形式</td><td>JSON Schema</td><td>JSON Schema</td><td>Schema JSON</td><td>MApp Schema</td><td>无（DOM 模型）</td></tr><tr><td>自定义组件</td><td>自定义组件注册</td><td>自定义字段</td><td>assets.components + setter</td><td>四件套（formConfig/initValue）</td><td>addType + traits</td></tr><tr><td>运行时分离</td><td>单进程</td><td>单进程</td><td>模拟 iframe</td><td>双进程（iframe runtime）</td><td>单进程（iframe 同上下文）</td></tr><tr><td>导出产物</td><td>JSON Schema</td><td>JSON Schema</td><td>Schema JSON</td><td>DSL JSON</td><td>HTML + CSS</td></tr><tr><td>学习曲线</td><td>缓（写 JSON）</td><td>中（理解领域模型）</td><td>陡（理解引擎/物料/插件）</td><td>缓（跑起来就能拖）</td><td>缓（拖 DOM）</td></tr><tr><td>适合场景</td><td>中后台 CRUD</td><td>复杂表单</td><td>定制化设计器</td><td>H5 活动页</td><td>营销落地页</td></tr><tr><td>不适合场景</td><td>复杂表单联动、自由布局</td><td>列表/页面布局</td><td>快速交付、运营自助</td><td>中后台表单</td><td>表单、数据看板</td></tr></tbody></table><h3 id="三问选型决策树" tabindex="-1">三问选型决策树 <a class="header-anchor" href="#三问选型决策树" aria-label="Permalink to &quot;三问选型决策树&quot;">​</a></h3><p>面对任何需求，先问三个问题：</p><p><strong>第一问：这是表单还是页面？</strong></p><ul><li>如果核心是<strong>表单</strong>（字段多、校验复杂、联动多）→ 优先 Formily。Formily 的领域模型是五个产品里对表单抽象最彻底的——Field 模型、reactions 联动、异步校验、生命周期钩子，专为复杂表单设计。</li><li>如果核心是<strong>页面</strong>（列表、卡片、布局、导航）→ 看第二问。</li></ul><p><strong>第二问：要约束还是要自由？</strong></p><ul><li>如果运营/业务人员要<strong>自助搭建</strong>、要&quot;所见即所得&quot;、要快速交付 → amis。Schema 约束让非技术人员也能搭出结构清晰的页面。</li><li>如果需要<strong>高度定制化</strong>（自定义设计器、自定义物料、自定义插件）→ lowcode-engine。它的引擎/物料/插件三层架构是五个产品里扩展性最强的。</li><li>如果要<strong>自由排版</strong>（像素级布局、营销页、邮件模板）→ GrapesJS。直接操作 DOM，想怎么拖怎么拖。</li><li>如果是 H5 活动页（绝对布局 + 动画 + 跨端）→ tmagic-editor。它的 MApp DSL 可以跨端渲染（移动端、小程序）。</li></ul><p><strong>第三问：单端还是跨端？</strong></p><ul><li>如果只在 PC 端跑 → amis / Formily / GrapesJS 都可以。</li><li>如果要跨端（PC + 移动 + 小程序）→ tmagic-editor。它的 DSL 运行时可以部署到多个端。</li><li>如果要完全自定义渲染目标 → lowcode-engine。你可以写自己的渲染器，把 Schema 渲染成任何东西。</li></ul><h3 id="两个对照产品" tabindex="-1">两个对照产品 <a class="header-anchor" href="#两个对照产品" aria-label="Permalink to &quot;两个对照产品&quot;">​</a></h3><p>规格里还提到 Appsmith 和 ToolJet 作为对照（不做主线 lab）。它们是<strong>平台型应用搭建器</strong>——自带后端、数据库、权限，一站式构建内部工具。和五个主线产品的区别：</p><table tabindex="0"><thead><tr><th>维度</th><th>Appsmith / ToolJet</th><th>amis / Formily / lowcode / tmagic / GrapesJS</th></tr></thead><tbody><tr><td>自带后端</td><td>是（数据库 + API）</td><td>否（纯前端，后端自己接）</td></tr><tr><td>部署方式</td><td>Docker / 云服务</td><td>静态部署 / 自有服务</td></tr><tr><td>适合场景</td><td>内部工具快速搭建</td><td>前端页面/表单</td></tr><tr><td>学习曲线</td><td>缓（全栈一站式）</td><td>中（要接后端）</td></tr><tr><td>定制化</td><td>低（平台约束）</td><td>高（代码可控）</td></tr></tbody></table><p>如果团队没有后端、要快速搭内部工具，Appsmith/ToolJet 更合适；如果团队有前端能力、要深度定制，五个主线产品更灵活。</p><h2 id="产品对照" tabindex="-1">产品对照 <a class="header-anchor" href="#产品对照" aria-label="Permalink to &quot;产品对照&quot;">​</a></h2><p>本章本身就是对照章节，这里给一个&quot;同一需求，五种实现&quot;的对比：</p><p><strong>需求</strong>：客户运营后台——概览卡片 + 客户列表 CRUD + 复杂表单 + 导出。</p><table tabindex="0"><thead><tr><th>产品</th><th>实现方式</th><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>amis</td><td>一个 JSON Schema 搞定列表+表单+弹窗</td><td>最快、Schema 可复用</td><td>复杂表单联动弱、样式定制难</td></tr><tr><td>Formily</td><td>表单用 Formily，列表自己写</td><td>表单能力最强</td><td>非表单部分要自己写</td></tr><tr><td>lowcode-engine</td><td>设计器拖组件 + 自定义物料</td><td>最灵活、可运营自助</td><td>搭建成本高、学习曲线陡</td></tr><tr><td>tmagic-editor</td><td>拖拽搭 H5 风格页面</td><td>跨端、动画好</td><td>中后台风格不搭</td></tr><tr><td>GrapesJS</td><td>自由画布拖 DOM</td><td>最自由</td><td>表单/数据能力缺失</td></tr></tbody></table><p><strong>推荐方案</strong>：amis 做列表和页面骨架 + Formily 嵌入做复杂表单（capstone 第 15 章就是这个组合）。</p><h2 id="动手实现" tabindex="-1">动手实现 <a class="header-anchor" href="#动手实现" aria-label="Permalink to &quot;动手实现&quot;">​</a></h2><p>本章是纯文档章节，没有代码和 lab。但你可以做一个选型练习：</p><h3 id="选型练习" tabindex="-1">选型练习 <a class="header-anchor" href="#选型练习" aria-label="Permalink to &quot;选型练习&quot;">​</a></h3><p>假设你要做以下三个需求，分别选哪个产品？为什么？</p><ol><li><strong>营销活动落地页</strong>：运营要频繁换 banner、调布局、加按钮，上线后导出静态 HTML 部署到 CDN。</li><li><strong>内部审批表单</strong>：含多级联动（省→市→区）、异步校验（用户名是否已存在）、条件显隐（选&quot;其他&quot;时显示备注框）。</li><li><strong>可视化大屏设计器</strong>：运营拖拽图表组件、配置数据源、设计布局，生成的大屏要在 PC 和移动端都能看。</li></ol><p>参考答案：1→GrapesJS（自由画布 + HTML 导出）；2→Formily（复杂表单联动 + 异步校验）；3→lowcode-engine 或 tmagic-editor（自定义设计器 + 跨端渲染）。</p><h3 id="选型验证清单" tabindex="-1">选型验证清单 <a class="header-anchor" href="#选型验证清单" aria-label="Permalink to &quot;选型验证清单&quot;">​</a></h3><p>选定产品后，用这个清单验证是否合适：</p><ul><li>[ ] 核心场景是否在产品的&quot;甜蜜区&quot;？</li><li>[ ] 自定义能力是否足够（组件、样式、逻辑）？</li><li>[ ] 团队学习成本是否可接受？</li><li>[ ] 导出/部署产物是否符合要求？</li><li>[ ] 社区活跃度和文档质量是否支撑长期使用？</li></ul><h2 id="跑不起来" tabindex="-1">跑不起来？ <a class="header-anchor" href="#跑不起来" aria-label="Permalink to &quot;跑不起来？&quot;">​</a></h2><p>本章是选型章节，没有代码可跑。但选型本身也会&quot;跑不起来&quot;——常见的选型失败模式：</p><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td>选了 amis 但表单联动做不了</td><td>amis 的表达式能力有限</td><td>嵌入 Formily 做复杂表单，或改用 Formily</td></tr><tr><td>选了 GrapesJS 但中后台做不动</td><td>自由画布不适合表单密集场景</td><td>改用 amis 或 Formily</td></tr><tr><td>选了 lowcode-engine 但进度卡住</td><td>学习曲线陡，物料/插件要自己写</td><td>先用 amis/Formily 快速出 MVP，再考虑 lowcode</td></tr><tr><td>选了 tmagic 但只做 PC 端</td><td>跨端优势没用上，徒增复杂度</td><td>改用 amis（纯 PC）或 GrapesJS（落地页）</td></tr><tr><td>强行用一个产品做所有事</td><td>没有产品能覆盖所有场景</td><td>组合使用：amis 页面 + Formily 表单 + GrapesJS 落地页</td></tr></tbody></table><h2 id="避坑清单" tabindex="-1">避坑清单 <a class="header-anchor" href="#避坑清单" aria-label="Permalink to &quot;避坑清单&quot;">​</a></h2><ol><li><strong>不要因为&quot;最火&quot;就选</strong>：lowcode-engine 虽然出自阿里、生态大，但它是为&quot;定制化设计器&quot;设计的，不是为&quot;快速搭页面&quot;设计的。快速交付选 amis，不是 lowcode-engine。</li><li><strong>不要因为&quot;最自由&quot;就选 GrapesJS</strong>：自由画布在表单/数据场景下是灾难——没有字段模型、没有校验、没有联动。GrapesJS 只适合视觉为主的页面。</li><li><strong>不要低估 amis 的能力</strong>：很多人觉得 amis 只是&quot;写 JSON&quot;，但它的 CRUD、弹窗、API 数据源、表达式能力足够覆盖 80% 的中后台场景。先考虑 amis，再考虑更复杂的方案。</li><li><strong>组合使用比单一产品更强</strong>：没有产品能覆盖所有场景。amis 做页面骨架 + Formily 做复杂表单 + GrapesJS 做营销页，是常见的组合。</li><li><strong>选型要看团队，不只是看产品</strong>：如果团队前端能力强，lowcode-engine 的灵活性是优势；如果团队偏后端，amis 的低代码门槛更友好。</li></ol><h3 id="选型的三个常见误区" tabindex="-1">选型的三个常见误区 <a class="header-anchor" href="#选型的三个常见误区" aria-label="Permalink to &quot;选型的三个常见误区&quot;">​</a></h3><p><strong>误区一：用一个产品做所有事。</strong> 很多团队选了 amis 就想用 amis 做一切——落地页、表单、大屏、甚至小程序。结果是每个场景都做得&quot;能用但不好用&quot;。正确的做法是按场景选产品，允许一个项目里用多个产品。</p><p><strong>误区二：只看功能列表，不看工程化。</strong> 选型时容易陷入&quot;功能对比表&quot;——A 有 X 功能，B 有 Y 功能。但实际开发中，工程化能力（构建、部署、版本管理、二次开发）比功能列表更重要。lowcode-engine 功能多但搭建成本高，amis 功能少但开箱即用——后者往往更适合快速交付。</p><p><strong>误区三：忽视社区和文档。</strong> 低代码产品的坑很多，遇到问题时社区和文档是唯一依靠。amis 的文档最完善、lowcode-engine 的社区最活跃、GrapesJS 的英文文档好但中文资料少——这些都是选型时要考虑的。</p><h2 id="小结与自测" tabindex="-1">小结与自测 <a class="header-anchor" href="#小结与自测" aria-label="Permalink to &quot;小结与自测&quot;">​</a></h2><h3 id="你应该记住的" tabindex="-1">你应该记住的 <a class="header-anchor" href="#你应该记住的" aria-label="Permalink to &quot;你应该记住的&quot;">​</a></h3><ul><li>五强在&quot;约束-自由&quot;光谱上：amis（最约束）&lt; Formily &lt; lowcode-engine &lt; tmagic-editor &lt; GrapesJS（最自由）</li><li>三问决策树：表单还是页面？约束还是自由？单端还是跨端？</li><li>amis 甜蜜区：中后台 CRUD；雷区：复杂表单联动、深度样式定制</li><li>Formily 甜蜜区：复杂表单；雷区：非表单页面</li><li>lowcode-engine 甜蜜区：定制化设计器；雷区：快速交付、运营自助</li><li>tmagic-editor 甜蜜区：H5 活动页、跨端；雷区：中后台表单</li><li>GrapesJS 甜蜜区：营销落地页、邮件模板；雷区：表单、数据看板</li><li>Appsmith/ToolJet：自带后端的内部工具平台，适合无后端团队</li></ul><h3 id="自测题" tabindex="-1">自测题 <a class="header-anchor" href="#自测题" aria-label="Permalink to &quot;自测题&quot;">​</a></h3><ol><li><strong>选择题</strong>：一个需求是&quot;营销活动落地页，运营要自由排版、导出静态 HTML&quot;，最适合的产品是？（A）amis；（B）Formily；（C）tmagic-editor；（D）GrapesJS。</li><li><strong>选择题</strong>：一个需求是&quot;内部审批表单，含省市区联动、异步校验、条件显隐&quot;，最适合的产品是？（A）amis；（B）Formily；（C）lowcode-engine；（D）GrapesJS。</li><li><strong>思考题</strong>：为什么说&quot;没有银弹&quot;？能不能设计一个产品同时覆盖 amis 的中后台、Formily 的表单、GrapesJS 的自由画布？为什么现有产品都没做到？</li></ol><h3 id="自测题参考答案" tabindex="-1">自测题参考答案 <a class="header-anchor" href="#自测题参考答案" aria-label="Permalink to &quot;自测题参考答案&quot;">​</a></h3><ol><li>答案 D。GrapesJS 的自由画布和 HTML 导出正好匹配营销落地页场景。amis 的 Schema 约束太死，tmagic 的 DSL 导出不是纯 HTML，Formily 是表单不是页面。</li><li>答案 B。Formily 的领域模型专为复杂表单设计——reactions 联动、异步校验、条件显隐都是一等公民。amis 的表达式能力有限，lowcode-engine 杀鸡用牛刀，GrapesJS 没有表单能力。</li><li>&quot;没有银弹&quot;的本质是<strong>约束和自由不可兼得</strong>。约束越强（amis），结构越清晰、越可预测，但灵活度越低；自由越强（GrapesJS），灵活度越高，但结构越乱、越难维护。中间的产品（Formily/lowcode/tmagic）在某一个维度上做得更深（表单/设计器/跨端），但不可能同时在所有维度都做到极致。如果硬要做一个&quot;全能产品&quot;，结果往往是&quot;什么都能做但什么都做不好&quot;——这就是为什么低代码领域会分化出五个定位不同的产品。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>第 15 章综合实战——用 amis 做页面骨架 + Formily 做复杂表单，完成一个完整的&quot;客户运营后台&quot;（概览 + CRUD + 复杂表单 + 导出），并跑通 E2E。这是产品实战卷的收尾章，验证你对 amis 和 Formily 的组合使用能力。</p>',52))])}const b=d(s,[["render",n]]);export{g as __pageData,b as default};
